import java.util.HashSet;
import java.util.Scanner;

public class wedss {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int nPoints = sc.nextInt();
        if (nPoints <= 11) {
            long[][] pts = new long[nPoints][5];

            for (int index = 0; index < nPoints; index++) {
                for (int dim = 0; dim < 5; dim++) {
                    pts[index][dim] = sc.nextLong();
                }
            }

            long[][][] vecs = new long[nPoints][nPoints][5];
            for (int i = 0; i < nPoints; i++) {
                for (int j = 0; j < nPoints; j++) {
                    for (int k = 0; k < 5; k++) {
                        vecs[i][j][k] = pts[j][k] - pts[i][k];
                    }
                }
            }

            HashSet<Integer> removeSet = new HashSet<>();

            for (int i = 0; i < nPoints; i++) {
                boolean foundFlag = false;
                for (int j = 0; j < nPoints; j++) {
                    for (int k = 0; k < nPoints; k++) {
                        if (!vectorsEqual(vecs[i][j], vecs[i][k]) && vectorsDot(vecs[i][j], vecs[i][k])) {
                            removeSet.add(i + 1);
                            foundFlag = true;
                            break;
                        }
                    }
                    if (foundFlag) break;
                }
            }

            System.out.println(nPoints - removeSet.size());
            for (int i = 0; i < nPoints; i++) {
                if (!removeSet.contains(i + 1))
                    System.out.println(i + 1);
            }
        } else {
            System.out.println(0);
        }
    }

    private static boolean vectorsEqual(long[] a, long[] b) {
        for (int i = 0; i < 5; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    private static boolean vectorsDot(long[] a, long[] b) {
        long sum = 0;
        for (int i = 0; i < 5; i++) {
            sum += a[i] * b[i];
        }
        return sum > 0;
    }
}
